import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            adj.get(u).add(new int[]{v, w});
            adj.get(v).add(new int[]{u, w});
        }
        int from = sc.nextInt();
        int to = sc.nextInt();

        int[] cost = new int[n];
        Arrays.fill(cost, Integer.MAX_VALUE);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[1], b[1]));
        cost[from] = 0;
        pq.offer(new int[]{from, 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int city = top[0];
            int c = top[1];
            if (c > cost[city]) {
                continue;
            }
            for (int[] road : adj.get(city)) {
                int next = road[0];
                int price = road[1];
                if (c + price < cost[next]) {
                    cost[next] = c + price;
                    pq.offer(new int[]{next, cost[next]});
                }
            }
        }
        int answer = cost[to] == Integer.MAX_VALUE ? -1 : cost[to];
        System.out.println("Cost: " + answer);
    }
}
